 for lam in partitions(k):
  def rec(i,remaining):
   if i==len(lam):return not remaining
   ell=lam[i];R=list(remaining)
   for mask in range(1,1<<len(R)):
    S=[R[j] for j in range(len(R)) if mask>>j&1]
    if all(m%ell==0 for m in S) and sum(m//ell for m in S)==b:
     rem=tuple(R[j] for j in range(len(R)) if not(mask>>j&1))
     if rec(i+1,rem):return True
   return False
  if rec(0,tuple(point_cycles)):return True
